SELECT /* QueryID : com.demo.proworks.pug.selectListPug */ PUG_ID AS pugId, PJT_ID AS pjtId, USER_ID AS userId, NAME AS userName, POSITION AS userPosition, GRP_ID AS grpId, GRP_NAME AS grpName FROM ( SELECT PUG.PUG_ID, PUG.PJT_ID, PUG.USER_ID, PUG.GRP_ID, U.NAME, U.POSITION, G.GRP_NAME, CEIL((@ROWNUM := @ROWNUM + 1) / #{pageSize}) AS PAGE FROM (SELECT @ROWNUM := 0) R, PROJECT_USER_GROUP PUG JOIN USERS U ON PUG.USER_ID = U.USER_ID JOIN GROUPS G ON PUG.GRP_ID = G.GRP_ID WHERE PUG.PJT_ID = #{pjtId}
AND U.USER_ID LIKE CONCAT('%', #{scUserId}, '%')
AND U.NAME LIKE CONCAT('%', #{scUserName}, '%')
AND G.GRP_NAME LIKE CONCAT('%', #{scGrpName}, '%')
AND U.POSITION LIKE CONCAT('%', #{scUserPosition}, '%')
ORDER BY PUG.PUG_ID DESC ) A WHERE A.PAGE = #{pageIndex}
